concepts.text:
library ieee;
use ieee.std_logic_1164.all;
entity dff is
  port (clk, rst, d : in  std_logic;
        q          : out std_logic);
end dff;
architecture rtl of dff is
begin
  process (clk, rst)
  begin
    if rst = '1' then q <= '0';
    elsif rising_edge(clk) then q <= d;
    end if;
  end process;
end rtl;

questions.questionText:
Assume VHDL-2008 with ieee.std_logic_1164 and ieee.numeric_std. The testbench below starts at time 0 and is stopped at 200 ns. What value does cnt hold at 200 ns?

signal clk : std_logic := '0';
signal cnt : unsigned(3 downto 0) := (others => '0');
...
clk <= not clk after 5 ns;

process (clk)
begin
  if rising_edge(clk) then
    cnt <= cnt + 1;
  end if;
end process;
